import json
import re
from datetime import datetime, timezone, timedelta

normal = (_items[0].get("json") or {}).get("normal", {}) if _items else {}
text = str(normal.get("text") or "").strip()
def quote(value): return "'" + str(value).replace("'", "''") + "'"
parts = re.split(r"\s+", text)
command = (parts.pop(0) if parts else "").lower()
command = re.sub(r"@\w+$", "", command)
arg = " ".join(parts).strip()
def amount_of(value):
    match = re.search(r"(\d+(?:[.,]\d+)?)\s*(jt|juta|rb|ribu|k)?", value.lower())
    if not match: return None
    number = float(match.group(1).replace(",", "."))
    unit = match.group(2) or ""
    if unit in ("jt", "juta"): number *= 1_000_000
    elif unit in ("rb", "ribu", "k"): number *= 1_000
    return round(number)
help_text = "\n".join(["Perintah yang tersedia:", "/rekap — rekap bulan ini", "/saldo — saldo tiap dompet", "/dompet - daftar / tambah dompet", "/anggaran — pemakaian dan sisa anggaran", "/pindah 100000 BCA GoPay — pindah dana antar dompet", "/hapus OUT-0001 — hapus transaksi tertentu", "/undo — batalkan transaksi terakhir", "/rutin — kelola transaksi rutin", "/ingatkan — pengingat waktu"])
if command == "/undo": sql = "select public.undo_terakhir() as output"
elif command == "/saldo": sql = "select public.saldo_text() as output"
elif command == "/anggaran":
    tokens = arg.split()
    sub = tokens[0].lower() if tokens else ""
    if sub in ("hapus", "delete"):
        nama = " ".join(tokens[1:]).strip()
        sql = "select public.anggaran_hapus(" + quote(nama) + ") as output" if nama else "select " + quote("Format: /anggaran hapus makanan") + "::text as output"
    elif sub in ("set", "isi", "atur"):
        tokens = tokens[1:]
        nominal = amount_of(tokens[-1]) if len(tokens) >= 2 else None
        nama = " ".join(tokens[:-1]).strip() if len(tokens) >= 2 else ""
        sql = "select public.anggaran_set(" + quote(nama) + ", " + str(nominal) + ") as output" if nama and nominal else "select " + quote("Format: /anggaran makanan 3000000") + "::text as output"
    elif len(tokens) >= 2 and amount_of(tokens[-1]) is not None:
        nama = " ".join(tokens[:-1]).strip()
        sql = "select public.anggaran_set(" + quote(nama) + ", " + str(amount_of(tokens[-1])) + ") as output"
    else:
        sql = "select public.anggaran_text() as output"
elif command == "/hapus":
    if re.search(r"\bjangan\b", arg, re.I):
        sql = "select " + quote("Oke, tidak menghapus apa pun.") + "::text as output"
    elif not arg:
        sql = "select " + quote("Format: /hapus OUT-0001 atau /hapus beli kecap") + "::text as output"
    elif re.fullmatch(r"(?i)(in|out)[- ]?\d{1,6}", arg.strip()):
        kode_arg = re.sub(r"(?i)^(in|out)[- ]?", lambda m: m.group(1).upper() + "-", arg.strip())
        sql = "select public.hapus_transaksi(" + quote(kode_arg) + ") as output"
    else:
        sql = "select public.hapus_cari(" + quote(arg) + ") as output"
elif command == "/pindah":
    clean = re.sub(r"\b(dari|ke)\b", " ", arg, flags=re.I)
    clean = re.sub(r"\s+", " ", clean).strip()
    match = re.match(r"^([\d.,]+\s*(?:jt|juta|rb|ribu|k)?)\s+(\S.*?)\s+(\S.*)$", clean, re.I)
    amount = amount_of(match.group(1)) if match else None
    if not match or amount is None or amount < 1: sql = "select " + quote("Format: /pindah 100000 BCA GoPay") + "::text as output"
    else: sql = "select public.pindah_dana(" + str(amount) + ", " + quote(match.group(2).strip()) + ", " + quote(match.group(3).strip()) + ", " + quote("") + ", null) as output"
elif command == "/rutin":
    tokens = arg.split()
    sub = tokens.pop(0).lower() if tokens else ""
    if sub in ("", "daftar", "list"):
        sql = "select public.rutin_daftar() as output"
    elif sub == "hapus":
        nama = " ".join(tokens).strip()
        sql = "select public.rutin_hapus(" + quote(nama) + ") as output" if nama else "select " + quote("Format: /rutin hapus listrik") + "::text as output"
    elif sub in ("matikan", "nonaktif", "off"):
        nama = " ".join(tokens).strip()
        sql = "select public.rutin_set(" + quote(nama) + ", false) as output" if nama else "select " + quote("Format: /rutin matikan listrik") + "::text as output"
    elif sub in ("hidupkan", "aktifkan", "aktif", "on"):
        nama = " ".join(tokens).strip()
        sql = "select public.rutin_set(" + quote(nama) + ", true) as output" if nama else "select " + quote("Format: /rutin hidupkan listrik") + "::text as output"
    elif sub == "tambah":
        jenis = "Pengeluaran"
        if tokens and tokens[-1].lower() in ("masuk", "pemasukan"):
            jenis = "Pemasukan"
            tokens = tokens[:-1]
        nama = " ".join(tokens[:-2]).strip() if len(tokens) >= 3 else ""
        nominal = amount_of(tokens[-2]) if len(tokens) >= 3 else None
        tanggal = int(tokens[-1]) if len(tokens) >= 3 and re.fullmatch(r"\d{1,2}", tokens[-1]) else None
        kategori = "Gaji" if jenis == "Pemasukan" else "Tagihan"
        if not nama or nominal is None or tanggal is None:
            sql = "select " + quote("Format: /rutin tambah listrik 350000 5") + "::text as output"
        else:
            sql = "select public.rutin_tambah(" + quote(nama) + ", " + str(nominal) + ", " + str(tanggal) + ", " + quote(jenis) + ", " + quote(kategori) + ") as output"
    else:
        sql = "select " + quote("Perintah rutin: /rutin · /rutin tambah listrik 350000 5 · /rutin hapus listrik · /rutin matikan listrik") + "::text as output"
elif command == "/ingatkan":
    tokens = arg.split()
    sub = tokens[0].lower() if tokens else ""
    if not tokens:
        sql = "select public.ingatkan_daftar() as output"
    elif sub in ("hapus", "delete", "stop"):
        sql = "select public.ingatkan_hapus(" + tokens[1] + ") as output" if len(tokens) >= 2 and tokens[1].isdigit() else "select " + quote("Format: /ingatkan hapus 2") + "::text as output"
    else:
        teks_sisa = arg.strip()
        harian = False
        tanggal_sql = None
        nama_hari = {"senin": 1, "selasa": 2, "rabu": 3, "kamis": 4, "jumat": 5, "sabtu": 6, "minggu": 0}
        m_harian = re.match(r"^(harian|setiap|tiap)\s+", teks_sisa, re.I)
        if m_harian:
            harian = True
            teks_sisa = teks_sisa[m_harian.end():]
            m_penanda = re.match(r"^(pagi|siang|sore|malam|petang|hari)\s+", teks_sisa, re.I)
            if m_penanda: teks_sisa = teks_sisa[m_penanda.end():]
        m_iso = re.match(r"^([1-9]\d{3}-\d{2}-\d{2})\s+", teks_sisa)
        if m_iso:
            tanggal_sql = quote(m_iso.group(1)) + "::date"
            teks_sisa = teks_sisa[m_iso.end():]
        m_tgl = re.match(r"^(besok|esok|lusa|hari\s+ini|hari\s+(\w+)|(\w+))\s+", teks_sisa, re.I)
        if tanggal_sql is None and m_tgl:
            kata = re.sub(r"\s+", " ", m_tgl.group(1).lower())
            if kata in ("besok", "esok"):
                tanggal_sql = "((now() at time zone 'Asia/Jakarta')::date + 1)"
            elif kata == "lusa":
                tanggal_sql = "((now() at time zone 'Asia/Jakarta')::date + 2)"
            elif kata in ("hari ini", "hariini"):
                tanggal_sql = "((now() at time zone 'Asia/Jakarta')::date)"
            else:
                nama = kata.replace("hari ", "")
                if nama in nama_hari:
                    target = nama_hari[nama]
                    tanggal_sql = "((now() at time zone 'Asia/Jakarta')::date + case when ((%d - extract(dow from (now() at time zone 'Asia/Jakarta')::date)::int + 7) %% 7) = 0 then 7 else ((%d - extract(dow from (now() at time zone 'Asia/Jakarta')::date)::int + 7) %% 7) end)" % (target, target)
            if tanggal_sql is not None:
                teks_sisa = teks_sisa[m_tgl.end():]
        def rapikan_jam(h, mnt, penanda):
            h = int(h); mnt = int(mnt or 0)
            if penanda and penanda.lower() in ("sore", "malam", "petang") and h < 12: h += 12
            if penanda and penanda.lower() == "siang" and h < 11: h += 12
            return ("%02d:%02d" % (h, mnt)) if 0 <= h <= 23 and 0 <= mnt <= 59 else None
        jam_rapi = None
        m_jam = re.search(r"\bjam\s+(\d{1,2})(?:[:.](\d{2}))?\s*(pagi|siang|sore|malam|petang)?", teks_sisa, re.I)
        if m_jam:
            jam_rapi = rapikan_jam(m_jam.group(1), m_jam.group(2), m_jam.group(3))
            teks_sisa = teks_sisa[:m_jam.start()] + " " + teks_sisa[m_jam.end():]
        else:
            m_dua = re.search(r"\b(\d{1,2})[:.](\d{2})\b", teks_sisa)
            if m_dua:
                jam_rapi = rapikan_jam(m_dua.group(1), m_dua.group(2), None)
                teks_sisa = teks_sisa[:m_dua.start()] + " " + teks_sisa[m_dua.end():]
        teks = re.sub(r"\s+", " ", teks_sisa).strip(" -.,")
        if not teks or not jam_rapi:
            sql = "select " + quote("Sebutkan pengingat dan jamnya. Contoh: /ingatkan besok urus stnk jam 9 pagi") + "::text as output"
        elif harian:
            sql = "select public.ingatkan_tambah(" + quote(teks) + ", 'harian', null, '" + jam_rapi + "'::time) as output"
        else:
            if tanggal_sql is None:
                tanggal_sql = "((now() at time zone 'Asia/Jakarta')::date + case when (now() at time zone 'Asia/Jakarta')::time >= '" + jam_rapi + "'::time then 1 else 0 end)"
            sql = "select public.ingatkan_tambah(" + quote(teks) + ", 'sekali', ((" + tanggal_sql + ") + '" + jam_rapi + "'::time) at time zone 'Asia/Jakarta', null) as output"
elif command == "/dompet":
    tokens = arg.split()
    sub = tokens.pop(0).lower() if tokens else ""
    if sub in ("", "daftar", "list"):
        sql = "select public.saldo_text() as output"
    elif sub in ("tambah", "baru", "buat"):
        kind = "bank"
        if tokens and tokens[-1].lower() in ("bank", "ewallet", "e-wallet", "cash", "tunai"):
            last = tokens.pop().lower()
            kind = {"e-wallet": "ewallet", "tunai": "cash"}.get(last, last)
        nama = " ".join(tokens).strip()
        ident = re.sub(r"[^a-z0-9]+", "-", nama.lower()).strip("-")[:32]
        if not nama or not ident:
            sql = "select " + quote("Format: /dompet tambah BCA atau /dompet tambah Jago ewallet") + "::text as output"
        else:
            sql = ("with baru as (insert into public.accounts (id, name, kind) values (" + quote(ident) + ", " + quote(nama) + ", " + quote(kind) + ") on conflict (id) do nothing returning name) "
                   "select case when exists (select 1 from baru) then " + quote("Dompet " + nama + " dibuat (id: " + ident + ").") + " else " + quote("Dompet " + nama + " sudah ada (id: " + ident + ").") + " end as output")
    else:
        sql = "select " + quote("Perintah dompet: /dompet · /dompet tambah BCA") + "::text as output"
else: sql = "select " + quote(help_text) + "::text as output"
return [{"json": {"sql": sql}}]

